INSERT INTO iam.action_scope (code, display_name, description, requires_step_up, ordinal) VALUES
    ('DIAGNOSTIC_VIEW', 'View diagnosis', 'Read the priority queue, SKU diagnosis and canonical metrics.', false, 1),
    ('EVIDENCE_VIEW', 'View evidence', 'Open source-evidence references behind a canonical fact.', false, 2),
    ('MAPPING_RESOLVE', 'Resolve mapping', 'Confirm, reject or supersede a listing-to-SKU mapping candidate.', false, 3),
    ('INTERNAL_FACT_INTAKE', 'Enter internal facts', 'Enter or import cost, stock and finance facts.', false, 4),
    ('RECOMMENDATION_MANAGE', 'Manage recommendations', 'Validate, cancel or expire a recommendation and its tasks.', false, 5),
    ('TASK_ASSIGN', 'Assign tasks', 'Assign and reassign operating tasks.', false, 6),
    ('PRICE_CHANGE_APPROVE', 'Approve price change', 'Approve a price command or consume a bounded policy authorization.', true, 7),
    ('COMMERCIAL_POLICY_MANAGE', 'Manage commercial policy', 'Publish or retire a commercial policy version or scoped override.', true, 8),
    ('COMMAND_RESOLVE', 'Resolve command', 'Resolve an unknown result, readback mismatch or compensation.', true, 9),
    ('KILL_SWITCH_OPERATE', 'Operate kill switch', 'Disable or re-enable a write capability scope.', true, 10),
    ('AVAILABILITY_VIEW', 'View availability risk', 'Read the stockout and availability queue, its children and its evidence.', false, 11),
    ('INBOUND_ATTEST', 'Attest inbound supply', 'Record, amend or cancel an evidence-backed inbound supply attestation.', false, 12),
    ('AVAILABILITY_TASK_ACT', 'Act on an availability case', 'Record structured action evidence against an accountable availability case.', false, 14),
    ('AVAILABILITY_EXCEPTION_REQUEST', 'Request accepted risk', 'Request a scoped, expiring accepted exception against a calculated risk.', false, 15),
    ('AVAILABILITY_EXCEPTION_APPROVE', 'Approve accepted risk', 'Decide a scoped, expiring accepted exception at the authorised lane.', true, 16),
    ('SUPPLY_POLICY_MANAGE', 'Manage supply policy', 'Publish or retire lead-time, safety, demand, ownership, activation, priority and return-quality policy.', true, 13),
    ('ADVERTISING_VIEW', 'View advertising efficiency', 'Read the advertising control queue, its cases, evidence and outcomes.', false, 17),
    ('ADVERTISING_TASK_ACT', 'Act on an advertising case', 'Record structured action evidence against an accountable advertising case.', false, 18),
    ('ADVERTISING_EXCEPTION_REQUEST', 'Request advertising accepted risk', 'Request a scoped, expiring accepted exception against a calculated advertising risk.', false, 19),
    ('AD_BID_CHANGE_ENDORSE', 'Endorse a bid change', 'Give the distinct operational endorsement a bid change requires before final approval.', true, 20),
    ('AD_BID_CHANGE_APPROVE', 'Approve a bid change', 'Give the final per-command approval for an exact, bounded advertising bid change.', true, 21),
    ('ADVERTISING_POLICY_MANAGE', 'Manage advertising policy', 'Publish or retire advertising freshness, qualification, target, outcome, priority, SLO, lease and exposure policy.', true, 22),
    ('ADVERTISING_DECISION_EVIDENCE_VIEW', 'Read scoped advertising decision evidence', 'Read financial evidence only with Store and complete affected ProductVariant grants.', false, 23),
    ('ADVERTISING_MANUAL_EXECUTE', 'Execute an approved manual packet', 'Confirm and report legal manual execution of an exact approved packet.', true, 24),
    ('ADVERTISING_MANUAL_VERIFY', 'Independently verify manual configuration', 'Verify an exact native observation independently of the executor.', true, 25),
    ('ADVERTISING_MANUAL_ENDORSE', 'Endorse an exact manual packet', 'Give distinct operational endorsement to an exact manual business proposal.', true, 26),
    ('ADVERTISING_MANUAL_APPROVE', 'Approve an exact manual packet', 'Give Owner approval to an endorsed exact manual business proposal.', true, 27),
    ('ADVERTISING_TECHNICAL_STOP', 'Advertising technical stop', 'Explicit Platform/Security stop responsibility on the granted scope.', true, 28),
    ('ADVERTISING_TECHNICAL_ATTEST', 'Advertising technical attestation', 'Explicit Platform/Security recovery attestation on the granted scope.', true, 29),
    ('LISTING_CONVERSION_VIEW', 'View listing conversion', 'Read Listing Health, retained-visit conversion, candidates, actions and outcomes.', false, 30),
    ('LISTING_ACTION_PREPARE', 'Prepare listing action', 'Author a candidate comparison or an exact listing action for review.', false, 31),
    ('LISTING_ACTION_REVIEW', 'Review listing action', 'Attest the exact Russian text and the facts of a listing action as a person other than its author.', true, 32),
    ('LISTING_ACTION_APPROVE_ORDINARY', 'Approve ordinary listing action', 'Give the final approval for a listing action below both material triggers.', true, 33),
    ('LISTING_ACTION_APPROVE_MATERIAL', 'Approve material listing action', 'Give the final approval for a listing action that crosses a material trigger.', true, 34),
    ('LISTING_ACTION_LAUNCH', 'Launch listing action', 'Launch an approved listing action and acquire its exposure allowance.', true, 35),
    ('LISTING_MANUAL_EXECUTE', 'Execute listing manual packet', 'Report the execution of a governed manual listing packet.', true, 36),
    ('LISTING_MANUAL_VERIFY', 'Verify listing manual execution', 'Verify management-side match and display evidence independently of the executor.', true, 37),
    ('LISTING_CONTAINMENT_STOP', 'Stop listing scope', 'Record a technical or business stop at an exact listing scope.', true, 38),
    ('LISTING_CONTAINMENT_ATTEST', 'Attest listing repair', 'Attest, as the cause owner, that a contained cause is repaired.', true, 39),
    ('LISTING_CONTAINMENT_CONSENT', 'Consent to listing reenablement', 'Consent, as the business owner, to reenabling a contained listing scope.', true, 40),
    ('LISTING_PROMOTION_MANAGE', 'Manage promotion engagement', 'Adopt, exit and release simple promotion engagements on the governed manual path.', true, 41),
    ('LISTING_OUTCOME_EVALUATE', 'Evaluate listing outcome', 'Record qualified evidence under the exact frozen listing evaluation plan.', false, 42),
    ('LISTING_DECISION_EVIDENCE_VIEW', 'Read listing decision evidence', 'Read financial evidence only within the granted store and affected product scopes.', false, 43),
    ('LISTING_CALIBRATION_PREPARE', 'Prepare listing calibration', 'Prepare an exact scoped calibration package with source evidence.', true, 44),
    ('LISTING_CALIBRATION_VALIDATE', 'Validate listing calibration', 'Professionally validate the exact complete calibration package.', true, 45),
    ('LISTING_CALIBRATION_ACCEPT', 'Accept listing calibration', 'Owner accepts and activates an exact professionally validated package.', true, 46);
INSERT INTO iam.business_role (code, display_name, description, ordinal) VALUES
    ('OWNER', 'Owner', 'Accountable for commercial policy, approvals and enablement decisions.', 1),
    ('OPERATIONS', 'Operations', 'Runs the daily diagnostic loop, mapping, tasks and price proposals.', 2),
    ('FINANCE', 'Finance', 'Owns cost, fee and settlement facts and reviews profit evidence.', 3),
    ('READ_ONLY', 'Read only', 'Reads diagnosis and evidence without changing any operating state.', 4),
    ('MARKETPLACE_OPERATOR', 'Marketplace operator', 'Restores channel availability for an exact listing, store and fulfillment mode.', 5),
    ('PRODUCT_PROCUREMENT', 'Product and procurement', 'Owns inbound attestation and the lead-time and safety policy.', 6),
    ('TECH_DATA', 'Technical data', 'Repairs stock, mapping, ownership and source defects.', 7),
    ('FINANCE_ANALYST', 'Finance analyst', 'Resolves profit and cost-data blockers behind an availability decision.', 8),
    ('OPS_LEAD', 'Operations lead', 'Approves bounded accepted risk and owns the operating response.', 9),
    ('RISK_AUTHORITY', 'Risk authority', 'Owner-designated approver for critical, repeated or material accepted risk.', 10),
    ('AUDITOR', 'Auditor', 'Reads availability risk, cases and decisions without changing any state.', 11);
