INSERT INTO mart.diagnosis_rule (rule_code, rule_version, ordinal, display_name, statement, default_severity, blocks_execution, status) VALUES
    ('DATA_BLOCKED', 1, 1, 'Data blocked', 'Mapping is unresolved, a required profit input is missing, or the freshest input is older than the domain freshness target. Later rules are declined for this subject.', 'CRITICAL', true, 'ACTIVE'),
    ('NEGATIVE_MARGIN', 1, 2, 'Negative margin', 'Operational contribution profit is available and not positive.', 'CRITICAL', true, 'ACTIVE'),
    ('STOCKOUT_RISK', 1, 3, 'Stockout risk', 'Platform available units are zero, or stock cover days are below the configured safety horizon while sales continue.', 'CRITICAL', true, 'ACTIVE'),
    ('HIGH_RETURN', 1, 4, 'High return rate', 'Return rate is available and exceeds the configured threshold over a window with enough completed units to be meaningful.', 'WARNING', false, 'ACTIVE'),
    ('LOW_IMPRESSION', 1, 5, 'Low impressions', 'Impressions are available and fall below the configured floor for the window, indicating an exposure problem rather than a listing one.', 'WARNING', false, 'ACTIVE'),
    ('LOW_CLICK_THROUGH', 1, 6, 'Low click-through rate', 'Impressions are sufficient and click-through rate is below the configured floor.', 'WARNING', false, 'ACTIVE'),
    ('LOW_CONVERSION', 1, 7, 'Low conversion', 'Clicks or visits are sufficient and conversion rate is below the configured floor.', 'WARNING', false, 'ACTIVE'),
    ('ADVERTISING_INEFFICIENT', 1, 8, 'Advertising inefficient', 'Advertising cost of sale is available and exceeds the configured ceiling over the window.', 'WARNING', false, 'ACTIVE'),
    ('PRICE_BELOW_MINIMUM', 1, 9, 'Price below break-even', 'The observed selling price is below the computed break-even price, so every further unit sold at it loses money. A commercial floor above break-even is applied separately by the guardrail.', 'CRITICAL', true, 'ACTIVE');
