    ('STOCKOUT_RISK', 1, 'PLATFORM_AVAILABLE_UNITS', 'REQUIRED'),
    ('STOCKOUT_RISK', 1, 'STOCK_COVER_DAYS', 'OPTIONAL'),
    ('STOCKOUT_RISK', 1, 'INTERNAL_AVAILABLE_UNITS', 'OPTIONAL'),
    ('HIGH_RETURN', 1, 'RETURN_RATE', 'REQUIRED'),
    ('HIGH_RETURN', 1, 'COMPLETED_UNITS', 'REQUIRED'),
    ('LOW_IMPRESSION', 1, 'IMPRESSIONS', 'REQUIRED'),
    ('LOW_CLICK_THROUGH', 1, 'CLICK_THROUGH_RATE', 'REQUIRED'),
    ('LOW_CLICK_THROUGH', 1, 'IMPRESSIONS', 'REQUIRED'),
    ('LOW_CONVERSION', 1, 'CONVERSION_RATE', 'REQUIRED'),
    ('LOW_CONVERSION', 1, 'CLICKS', 'OPTIONAL'),
    ('ADVERTISING_INEFFICIENT', 1, 'AD_COST_OF_SALE', 'REQUIRED'),
    ('ADVERTISING_INEFFICIENT', 1, 'AD_SPEND', 'REQUIRED'),
    ('PRICE_BELOW_MINIMUM', 1, 'MINIMUM_PRICE', 'REQUIRED'),
    ('PRICE_BELOW_MINIMUM', 1, 'OBSERVED_SELLING_PRICE', 'REQUIRED');
INSERT INTO mart.metric_definition (metric_code, definition_version, display_name, unit_kind, formula_statement, domain, owner_label, status) VALUES
    ('IMPRESSIONS', 1, 'Impressions', 'COUNT', 'Sum of impressions over the window; NOT_AVAILABLE when no source publishes it.', 'FUNNEL', 'analyticsdecision', 'RETIRED'),
    ('CLICKS', 1, 'Clicks', 'COUNT', 'Sum of clicks over the window; NOT_AVAILABLE when no source publishes it.', 'FUNNEL', 'analyticsdecision', 'RETIRED'),
    ('CLICK_THROUGH_RATE', 1, 'Click-through rate', 'RATIO', 'CLICKS divided by IMPRESSIONS; undefined when impressions are absent or zero.', 'FUNNEL', 'analyticsdecision', 'RETIRED'),
    ('CONVERSION_RATE', 1, 'Conversion rate', 'RATIO', 'COMPLETED_UNITS divided by the strongest available visit or click measure.', 'FUNNEL', 'analyticsdecision', 'RETIRED'),
    ('COMPLETED_UNITS', 1, 'Completed units', 'COUNT', 'Sum of COMPLETED sale quantities over the window.', 'SALES', 'analyticsdecision', 'RETIRED'),
    ('COMPLETED_NET_SALES', 1, 'Completed net sales', 'MONEY', 'Sum of COMPLETED net amounts over the window in the store currency.', 'SALES', 'analyticsdecision', 'RETIRED'),
    ('RETAINED_UNITS', 1, 'Retained units', 'COUNT', 'Sum of RETAINED sale quantities for the requested retention window.', 'SALES', 'analyticsdecision', 'RETIRED'),
    ('RETAINED_NET_SALES', 1, 'Retained net sales', 'MONEY', 'Sum of RETAINED net amounts for the requested retention window.', 'SALES', 'analyticsdecision', 'RETIRED'),
    ('SETTLED_NET_SALES', 1, 'Settled net sales', 'MONEY', 'Sum of SETTLED net amounts over the window.', 'SALES', 'analyticsdecision', 'RETIRED'),
    ('RETURN_UNITS', 1, 'Returned units', 'COUNT', 'Sum of return quantities over the window across all return kinds.', 'RETURNS', 'analyticsdecision', 'RETIRED'),
    ('RETURN_RATE', 1, 'Return rate', 'RATIO', 'RETURN_UNITS divided by COMPLETED_UNITS; undefined when completed units are zero.', 'RETURNS', 'analyticsdecision', 'RETIRED'),
    ('PLATFORM_AVAILABLE_UNITS', 1, 'Platform available units', 'COUNT', 'Latest observed available quantity per fulfillment mode, summed across modes.', 'INVENTORY', 'analyticsdecision', 'RETIRED'),
    ('INTERNAL_AVAILABLE_UNITS', 1, 'Internal available units', 'COUNT', 'Latest internal on-hand quantity less reserved quantity across warehouses.', 'INVENTORY', 'analyticsdecision', 'RETIRED'),
    ('STOCK_COVER_DAYS', 1, 'Stock cover days', 'DAYS', 'PLATFORM_AVAILABLE_UNITS divided by mean daily COMPLETED_UNITS over the window.', 'INVENTORY', 'analyticsdecision', 'RETIRED'),
    ('AD_SPEND', 1, 'Advertising spend', 'MONEY', 'Sum of advertising spend attributable to the subject over the window.', 'ADVERTISING', 'analyticsdecision', 'RETIRED'),
    ('AD_COST_OF_SALE', 1, 'Advertising cost of sale', 'RATIO', 'AD_SPEND divided by COMPLETED_NET_SALES; undefined when net sales are zero.', 'ADVERTISING', 'analyticsdecision', 'RETIRED'),
    ('PLATFORM_FEES', 1, 'Platform fees', 'MONEY', 'Sum of platform fee amounts over the window excluding advertising.', 'COST', 'analyticsdecision', 'RETIRED'),
    ('UNIT_COST', 1, 'Unit purchase cost', 'MONEY', 'Cost version in force at the window end for the mapped internal variant.', 'COST', 'analyticsdecision', 'RETIRED'),
    ('RETURN_LOSS', 1, 'Return loss', 'MONEY', 'Sum of recorded return loss amounts over the window.', 'COST', 'analyticsdecision', 'RETIRED'),
    ('VARIABLE_TAX_ESTIMATE', 1, 'Variable tax estimate', 'MONEY', 'COMPLETED_NET_SALES multiplied by the finance input rate in force.', 'COST', 'analyticsdecision', 'RETIRED'),
    ('OPERATIONAL_CONTRIBUTION_PROFIT', 1, 'Operational contribution profit', 'MONEY', 'COMPLETED_NET_SALES less unit cost of completed units, platform fees, return loss, advertising spend and the variable tax estimate.', 'PROFIT', 'analyticsdecision', 'RETIRED'),
    ('SETTLED_CONTRIBUTION_PROFIT', 1, 'Settled contribution profit', 'MONEY', 'SETTLED_NET_SALES less unit cost of settled units, settled platform fees, return loss, advertising spend and the variable tax estimate.', 'PROFIT', 'analyticsdecision', 'RETIRED'),
    ('CONTRIBUTION_MARGIN', 1, 'Contribution margin', 'RATIO', 'OPERATIONAL_CONTRIBUTION_PROFIT divided by COMPLETED_NET_SALES.', 'PROFIT', 'analyticsdecision', 'RETIRED'),
    ('OBSERVED_SELLING_PRICE', 1, 'Observed selling price', 'MONEY', 'The most recent observed price a buyer pays, preferring a discounted amount over a selling amount over a list amount.', 'PROFIT', 'analyticsdecision', 'RETIRED'),
    ('MINIMUM_PRICE', 1, 'Break-even unit price', 'MONEY', 'Unit price at which unit contribution profit is exactly zero, given unit cost, the observed proportional fee rate, return loss per unit and the variable tax rate. A commercial floor above break-even is a policy decision applied by the guardrail, not part of this definition.', 'PROFIT', 'analyticsdecision', 'RETIRED'),
    ('DATA_COMPLETENESS', 1, 'Data completeness', 'RATIO', 'Share of the profit definition inputs that resolved to a canonical value.', 'QUALITY', 'analyticsdecision', 'RETIRED'),
    ('IMPRESSIONS', 2, 'Impressions', 'COUNT', 'Sum of impressions over the window; NOT_AVAILABLE when no source publishes it.', 'FUNNEL', 'analyticsdecision', 'ACTIVE'),
    ('CLICKS', 2, 'Clicks', 'COUNT', 'Sum of clicks over the window; NOT_AVAILABLE when no source publishes it.', 'FUNNEL', 'analyticsdecision', 'ACTIVE'),
    ('CLICK_THROUGH_RATE', 2, 'Click-through rate', 'RATIO', 'CLICKS divided by IMPRESSIONS; undefined when impressions are absent or zero.', 'FUNNEL', 'analyticsdecision', 'ACTIVE'),
    ('CONVERSION_RATE', 2, 'Conversion rate', 'RATIO', 'COMPLETED_UNITS divided by the strongest available visit or click measure.', 'FUNNEL', 'analyticsdecision', 'ACTIVE'),
    ('COMPLETED_UNITS', 2, 'Completed units', 'COUNT', 'Sum of COMPLETED sale quantities over the window.', 'SALES', 'analyticsdecision', 'ACTIVE'),
    ('COMPLETED_NET_SALES', 2, 'Completed net sales', 'MONEY', 'Sum of COMPLETED net amounts over the window in the store currency.', 'SALES', 'analyticsdecision', 'ACTIVE'),
    ('RETAINED_UNITS', 2, 'Retained units', 'COUNT', 'Sum of RETAINED sale quantities for the requested retention window.', 'SALES', 'analyticsdecision', 'ACTIVE'),
    ('RETAINED_NET_SALES', 2, 'Retained net sales', 'MONEY', 'Sum of RETAINED net amounts for the requested retention window.', 'SALES', 'analyticsdecision', 'ACTIVE'),
    ('SETTLED_NET_SALES', 2, 'Settled net sales', 'MONEY', 'Sum of SETTLED net amounts over the window.', 'SALES', 'analyticsdecision', 'ACTIVE'),
    ('RETURN_UNITS', 2, 'Returned units', 'COUNT', 'Sum of return quantities over the window across all return kinds.', 'RETURNS', 'analyticsdecision', 'ACTIVE'),
    ('RETURN_RATE', 2, 'Return rate', 'RATIO', 'RETURN_UNITS divided by COMPLETED_UNITS; undefined when completed units are zero.', 'RETURNS', 'analyticsdecision', 'ACTIVE'),
    ('PLATFORM_AVAILABLE_UNITS', 2, 'Platform available units', 'COUNT', 'Latest observed available quantity per fulfillment mode, summed across modes.', 'INVENTORY', 'analyticsdecision', 'ACTIVE'),
    ('INTERNAL_AVAILABLE_UNITS', 2, 'Internal available units', 'COUNT', 'Latest internal on-hand quantity less reserved quantity across warehouses.', 'INVENTORY', 'analyticsdecision', 'ACTIVE'),
    ('STOCK_COVER_DAYS', 2, 'Stock cover days', 'DAYS', 'PLATFORM_AVAILABLE_UNITS divided by mean daily COMPLETED_UNITS over the window.', 'INVENTORY', 'analyticsdecision', 'ACTIVE'),
    ('AD_SPEND', 2, 'Advertising spend', 'MONEY', 'Sum of advertising spend attributable to the subject over the window.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('AD_COST_OF_SALE', 2, 'Advertising cost of sale', 'RATIO', 'AD_SPEND divided by COMPLETED_NET_SALES; undefined when net sales are zero.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('PLATFORM_FEES', 2, 'Platform fees', 'MONEY', 'Sum of platform fee amounts over the exact half-open window excluding advertising and variable tax.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('UNIT_COST', 2, 'Unit purchase cost', 'MONEY', 'Cost version in force at the window end for the mapped internal variant.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('RETURN_LOSS', 2, 'Return loss', 'MONEY', 'Sum of recorded return loss amounts over the window.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('VARIABLE_TAX_ESTIMATE', 2, 'Variable tax estimate', 'MONEY', 'COMPLETED_NET_SALES multiplied by the finance input rate in force.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('OPERATIONAL_CONTRIBUTION_PROFIT', 2, 'Operational contribution profit', 'MONEY', 'COMPLETED_NET_SALES less unit cost of completed units, platform fees, return loss, advertising spend and a required sourced variable tax estimate; unavailable when any component is absent.', 'PROFIT', 'analyticsdecision', 'ACTIVE'),
    ('SETTLED_CONTRIBUTION_PROFIT', 2, 'Settled contribution profit', 'MONEY', 'SETTLED_NET_SALES less unit cost of settled units, settled platform fees, return loss, advertising spend and actual variable tax; unavailable when any component is absent.', 'PROFIT', 'analyticsdecision', 'ACTIVE'),
    ('CONTRIBUTION_MARGIN', 2, 'Contribution margin', 'RATIO', 'OPERATIONAL_CONTRIBUTION_PROFIT divided by COMPLETED_NET_SALES.', 'PROFIT', 'analyticsdecision', 'ACTIVE'),
    ('OBSERVED_SELLING_PRICE', 2, 'Observed selling price', 'MONEY', 'The most recent observed price a buyer pays, preferring a discounted amount over a selling amount over a list amount.', 'PROFIT', 'analyticsdecision', 'ACTIVE'),
    ('MINIMUM_PRICE', 2, 'Minimum price', 'MONEY', 'The least supported price whose exact projected profile components cover UNIT_COST plus REQUIRED_PROFIT_PER_UNIT plus SAFETY_BUFFER_PER_UNIT; every authority is versioned, sourced and currency-consistent.', 'PROFIT', 'analyticsdecision', 'ACTIVE'),
    ('DATA_COMPLETENESS', 2, 'Data completeness', 'RATIO', 'Share of the eight required canonical profit and commercial inputs that resolved, bound to the effective listing mapping.', 'QUALITY', 'analyticsdecision', 'ACTIVE'),
    ('PLATFORM_FEES_PER_UNIT', 2, 'Platform fees per completed unit', 'MONEY', 'PLATFORM_FEES over the exact half-open window divided by COMPLETED_UNITS; absence is not zero.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('RETURN_LOSS_PER_UNIT', 2, 'Return loss per completed unit', 'MONEY', 'RETURN_LOSS over the exact half-open window divided by COMPLETED_UNITS; absence is not zero.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('AD_SPEND_PER_UNIT', 2, 'Advertising spend per completed unit', 'MONEY', 'AD_SPEND over the exact half-open window divided by COMPLETED_UNITS; absence is not zero.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('VARIABLE_TAX_PER_UNIT', 2, 'Actual variable tax per completed unit', 'MONEY', 'Explicitly published VARIABLE_TAX fee amount over the exact half-open window divided by COMPLETED_UNITS; absence is not zero.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('REQUIRED_PROFIT_PER_UNIT', 2, 'Required profit per unit', 'MONEY', 'The effective sourced company-owned REQUIRED_PROFIT_PER_UNIT amount; no default is permitted.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('SAFETY_BUFFER_PER_UNIT', 2, 'Safety buffer per unit', 'MONEY', 'The effective sourced company-owned SAFETY_BUFFER_PER_UNIT amount; no default is permitted.', 'COST', 'analyticsdecision', 'ACTIVE'),
    ('BREAK_EVEN_PRICE', 2, 'Break-even price', 'MONEY', 'The least supported price whose projected profile components cover UNIT_COST; the projection is versioned by platform, account, Store and fulfilment mode.', 'PROFIT', 'analyticsdecision', 'ACTIVE'),
    ('AD_ELIGIBLE_TRAFFIC', 1, 'Eligible advertising traffic', 'COUNT', 'The official traffic denominator the applicable Conversion Definition names for this object and window.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('PROVIDER_ATTRIBUTED_CONVERSION', 1, 'Provider-attributed conversion', 'RATIO', 'Provider-attributed orders divided by the provider traffic denominator; a marketplace observation only, never canonical.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('AD_LINKED_ORDER_CONVERSION', 1, 'Ad-linked order conversion', 'RATIO', 'Deterministically ad-linked company Orders divided by eligible advertising traffic for the same object, window and complete affected set.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('AD_LINKED_COMPLETED_SALE_CONVERSION', 1, 'Ad-linked completed-sale conversion', 'RATIO', 'Deterministically ad-linked Completed Sales divided by eligible advertising traffic for the same object, window and complete affected set.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('AD_LINKED_RETAINED_SALE_CONVERSION', 1, 'Ad-linked retained-sale conversion', 'RATIO', 'Deterministically ad-linked Retained Sales divided by eligible advertising traffic for the same object, window and complete affected set.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('AD_ATTRIBUTION_GAP_RATIO', 1, 'Provider-to-canonical attribution gap', 'RATIO', 'Absolute difference between provider-attributed and canonical ad-linked sale events, over the canonical count; UNDEFINED when either side is absent.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('ALLOWABLE_CPA', 1, 'Allowable cost per acquisition', 'MONEY', 'The contribution a single ad-linked sale event of the stated stage may spend before it stops paying; carries the same stage as the conversion it is multiplied with.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('MAX_CPC', 1, 'Maximum cost per click', 'MONEY', 'Stage-consistent Allowable CPA multiplied by the stage-consistent ad-linked conversion rate; an economic ceiling, never an automatic bid target.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('ADVERTISING_CONTRIBUTION_PROFIT', 1, 'Advertising contribution profit', 'MONEY', 'Attributable net sales less COGS, commission and variable fees, fulfillment, return loss, promotion cost, variable tax and the official AD_SPEND for the same object and window.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('CONTRIBUTION_PROFIT_PER_AD_RUB', 1, 'Contribution profit per advertising rouble', 'RATIO', 'ADVERTISING_CONTRIBUTION_PROFIT divided by the existing AD_SPEND metric; UNDEFINED when spend is absent or zero, never zero when spend is unreported.', 'ADVERTISING', 'analyticsdecision', 'ACTIVE'),
    ('SETTLED_UNITS', 2, 'Settled units', 'COUNT', 'Sum of SETTLED sale quantities over the exact half-open business window; absent source remains unavailable.', 'SALES', 'analyticsdecision', 'ACTIVE');
INSERT INTO ops.ad_bid_command_transition (from_state, to_state, requires_lease, releases_lease, note) VALUES
    ('PENDING', 'LEASED', false, false, 'a worker claims the command through the leasing function'),
    ('PENDING', 'TERMINATED_WITHOUT_PROVIDER_CALL', false, false, 'a quarantine or kill activated before anything was sent'),
    ('LEASED', 'EXECUTING', true, false, 'the adapter call is about to be made'),
    ('LEASED', 'READBACK_PENDING', true, false, 'a governed retry must observe the current value at its new lease fence'),
    ('LEASED', 'PENDING', true, true, 'the worker released the claim without calling the platform'),
    ('LEASED', 'UNKNOWN_REQUIRES_READBACK', true, true, 'an abandoned retry preflight cannot restore permission to submit'),
    ('LEASED', 'TERMINATED_WITHOUT_PROVIDER_CALL', true, true, 'live pre-transmission revalidation refused the send'),
    ('EXECUTING', 'PLATFORM_PENDING', true, false, 'the platform accepted the request and reported asynchronous work'),
    ('EXECUTING', 'READBACK_PENDING', true, false, 'the platform answered synchronously and the value must be read back'),
    ('EXECUTING', 'RETRY_WAIT', true, true, 'a retriable transport or rate-limit condition occurred'),
    ('EXECUTING', 'UNKNOWN_REQUIRES_READBACK', true, true, 'the call timed out or returned an answer that cannot be classified'),
    ('EXECUTING', 'FAILED_FINAL', true, true, 'the platform rejected the request permanently'),
    ('PLATFORM_PENDING', 'READBACK_PENDING', true, false, 'the platform reported the asynchronous work as finished'),
    ('PLATFORM_PENDING', 'RETRY_WAIT', true, true, 'the status enquiry is not yet conclusive'),
    ('PLATFORM_PENDING', 'UNKNOWN_REQUIRES_READBACK', true, true, 'the status enquiry cannot be classified'),
    ('PLATFORM_PENDING', 'FAILED_FINAL', true, true, 'the platform reported the asynchronous work as rejected'),
    ('READBACK_PENDING', 'READBACK_MATCHED', true, true, 'a readback observed the exact approved target'),
    ('READBACK_PENDING', 'READBACK_MISMATCH', true, true, 'a readback observed the captured prior value'),
    ('READBACK_PENDING', 'LATER_CHANGE_OR_MISMATCH_INVESTIGATION', true, true, 'a readback observed a third value that nothing in this lineage wrote'),
    ('READBACK_PENDING', 'RETRY_WAIT', true, true, 'the readback is not yet available'),
    ('READBACK_PENDING', 'EXECUTING', true, false, 'only a retry preflight at this lease fence may authorize governed reentry'),
    ('READBACK_PENDING', 'UNKNOWN_REQUIRES_READBACK', true, true, 'the readback attempt itself could not be classified'),
    ('RETRY_WAIT', 'LEASED', false, false, 'the retry delay elapsed and a worker claimed the command again'),
    ('RETRY_WAIT', 'FAILED_FINAL', false, false, 'the retry budget is exhausted'),
    ('RETRY_WAIT', 'MANUAL_RESOLUTION', false, false, 'an operator took the command out of automatic handling'),
    ('RETRY_WAIT', 'TERMINATED_WITHOUT_PROVIDER_CALL', false, false, 'a quarantine or kill activated while the command was waiting'),
    ('UNKNOWN_REQUIRES_READBACK', 'READBACK_PENDING', false, false, 'a readback attempt is authorised; the write itself is never repeated'),
    ('UNKNOWN_REQUIRES_READBACK', 'MANUAL_RESOLUTION', false, false, 'an operator took the unresolved command over'),
    ('READBACK_MISMATCH', 'MANUAL_RESOLUTION', false, false, 'an operator took the mismatch over'),
    ('READBACK_MISMATCH', 'COMPENSATION_PENDING', false, false, 'an operator authorised restoring the captured prior bid'),
    ('LATER_CHANGE_OR_MISMATCH_INVESTIGATION', 'MANUAL_RESOLUTION', false, false, 'an operator took the externally-owned value over; nothing automatic may'),
    ('MANUAL_RESOLUTION', 'COMPENSATION_PENDING', false, false, 'an operator authorised restoring the captured prior bid'),
    ('MANUAL_RESOLUTION', 'READBACK_MATCHED', false, false, 'an operator confirmed the approved target against a matching readback'),
    ('MANUAL_RESOLUTION', 'FAILED_FINAL', false, false, 'an operator closed the command as failed'),
    ('COMPENSATION_PENDING', 'COMPENSATED', true, true, 'the captured prior bid was restored and read back'),
    ('COMPENSATION_PENDING', 'COMPENSATION_FAILED', true, true, 'the restore could not be completed'),
    ('COMPENSATION_PENDING', 'MANUAL_RESOLUTION', false, true, 'the restore was withdrawn and returned to an operator');
